const CATALOG_SEARCH_GZIP="";
const ASSORTMENT_META={"snapshot_at":"2026-10-08T18:11:14Z","source":"https://www.elcomspb.ru/","sitemap_source":"https://www.elcomspb.ru/sitemap-iblock-31.xml","sitemap_addresses":12833,"indexed_addresses":12847,"verified_product_cards":399,"verified_unique_articles":399,"checked_addresses":474,"known_unavailable_addresses":1,"main_menu_sections":144,"coverage_policy":"Все адреса карты сайта и текущие разделы включены в поиск. Технические параметры и артикулы подтверждены только для verified_product_cards; остальные карточки читать при подборе. Наличие всегда проверять онлайн."};
const ASSORTMENT_GZIP="";
let assortmentCache;
async function assortmentData(){
 if(assortmentCache)return assortmentCache;
 const bytes=Uint8Array.from(atob(ASSORTMENT_GZIP),c=>c.charCodeAt(0));
 assortmentCache=JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());
 return assortmentCache;
}
const transliteration={'А':'A','Б':'B','В':'V','Г':'G','Д':'D','Е':'E','Ё':'E','Ж':'ZH','З':'Z','И':'I','Й':'Y','К':'K','Л':'L','М':'M','Н':'N','О':'O','П':'P','Р':'R','С':'S','Т':'T','У':'U','Ф':'F','Х':'KH','Ц':'TS','Ч':'CH','Ш':'SH','Щ':'SHCH','Ъ':'','Ы':'Y','Ь':'','Э':'E','Ю':'YU','Я':'YA'};
function equipmentNorm(value){return String(value).toUpperCase().replace(/[А-ЯЁ]/g,c=>transliteration[c]??c).replace(/(\d),(\d)/g,'$1.$2').replace(/[^A-Z0-9.]/g,'');}
function equipmentTokens(query){
 return query.replace(/(\d),(\d)/g,'$1.$2').split(/[\s,;\/]+/).map(equipmentNorm).filter(Boolean).map(t=>t.replace(/^NMRV/,'NMRW'));
}
function supplierComponentType(item){
 if(!item.url.includes('/retail/pumps/'))return null;
 if(item.url.includes('/zapasnye-chasti-i-komplektuyushchie-dlya-nasosov/'))return 'pump_spare';
 const execution=item.attributes?.['Исполнение:']||item.attributes?.['Исполнение']||'';
 if(/без двигателя|б\s*\/\s*дв/i.test(execution+' '+item.title))return 'pump_part';
 if(/с двигателем|с\s+эл[.]?\s*дв/i.test(execution+' '+item.title))return 'pump_unit';
 return 'pump_candidate';
}
async function findCards(query,limit=8){
 if(typeof query!=='string'||query.length<2||query.length>160)throw Error('Запрос от 2 до 160 символов');
 const data=await assortmentData();const tokens=equipmentTokens(query);const combined=tokens.join('');
 const pumpDesignationQuery=/^(?:1?D|K|KM|TSN|NMSh|CR)\d/i.test(combined);
 const ranked=[];
 for(const item of data.items){
  const componentType=supplierComponentType(item);
  if(pumpDesignationQuery&&componentType==='pump_spare')continue;
  const body=item.search;const hits=tokens.filter(t=>body.includes(t));
  const articleMatch=item.article&&equipmentNorm(item.article)===combined;
  if(!articleMatch&&(!hits.length||hits.length<tokens.length))continue;
  const score=(articleMatch?100:0)+(body.includes(combined)?20:0)+(item.article?5:0)+(item.kind==='product'?5:0)+(componentType==='pump_part'?15:0)-body.length/10000;
  ranked.push({item,score});
 }
 ranked.sort((a,b)=>b.score-a.score);
 return {query,snapshot_at:ASSORTMENT_META.snapshot_at,indexed_addresses:ASSORTMENT_META.indexed_addresses,cards:ranked.slice(0,Math.min(limit,12)).map(({item})=>({url:item.url,title:item.title,article:item.article??null,article_verified:!!item.article,attributes:item.attributes??{},source_kind:item.kind,component_type:supplierComponentType(item),requires_card_verification:true})),total_matches:ranked.length,stock_checked:false,...(ranked.some(({item})=>item.url.includes('/retail/pumps/'))?{pump_unit_policy:rules.pump_unit_policy}:{}),notice:'Адрес из карты сайта — кандидат, а не подтверждение доступности товара. До итогового ответа проверить карточку через get_component_stock. Наличие из снимка не используется.'};
}

const catalogCache=new Map();
async function catalogPages(catalog){
 const id=catalog.document.id;
 if(catalogCache.has(id)){const value=catalogCache.get(id);catalogCache.delete(id);catalogCache.set(id,value);return value;}
 if(!catalog.pages_gzip)return [];
 const bytes=Uint8Array.from(atob(catalog.pages_gzip),c=>c.charCodeAt(0));
 const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
 const value=JSON.parse(await new Response(stream).text());
 if(catalogCache.size>=5)catalogCache.delete(catalogCache.keys().next().value);
 catalogCache.set(id,value);return value;
}
function catalogSummary(category){
 const documents=CATALOGS.map(c=>c.document).filter(d=>!category||d.category===category);
 return {snapshot_at:SNAPSHOT_AT,documents,total_documents:documents.length,indexed_documents:documents.filter(d=>d.status.startsWith('indexed')).length,indexed_pages:documents.reduce((n,d)=>n+(d.indexed_pages||0),0),categories:[...new Set(CATALOGS.map(c=>c.document.category))],notice:'Текст и OCR включены в поиск. Графики, схемы, размеры и неоднозначные числа следует проверять по оригиналу. Видео перечислено, но не анализировалось.'};
}
async function readCatalogPage(documentId,page){
 const catalog=CATALOGS.find(c=>c.document.id===documentId);
 if(!catalog)throw Error('Документ не найден. Использовать list_catalogs для выбора document_id.');
 if(!Number.isInteger(page)||page<1||page>catalog.document.page_count)throw Error('Страница вне диапазона документа.');
 const rows=await catalogPages(catalog);const row=rows.find(r=>r.page===page);
 if(!row)throw Error('Текст страницы не извлечён. Проверить статус документа.');
 return {...row,text:row.text.slice(0,32000),truncated:row.text.length>32000,source_url:catalog.document.source_url,source_modified:catalog.document.modified,requires_visual_review:!!row.ocr||row.text_status==='visual_only',notice:'Номер страницы относится к PDF, печатная нумерация может отличаться. OCR не подтверждает точность чисел или соответствие строк и столбцов.'};
}
let catalogSearchCache;
async function catalogSearchIndex(){
 if(catalogSearchCache)return catalogSearchCache;
 const bytes=Uint8Array.from(atob(CATALOG_SEARCH_GZIP),c=>c.charCodeAt(0));
 catalogSearchCache=JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());
 return catalogSearchCache;
}
function catalogExcerpt(text,tokens){
 if(text.length<=2600)return text;
 const lines=text.split('\n');const hits=[];
 for(let i=0;i<lines.length;i++)if(tokens.some(t=>norm(lines[i]).includes(t)))hits.push(i);
 if(!hits.length)return text.slice(0,2600);
 const indexes=new Set();
 for(const i of hits.slice(0,12))for(let j=Math.max(0,i-2);j<=Math.min(lines.length-1,i+3);j++)indexes.add(j);
 return [...indexes].sort((a,b)=>a-b).map(i=>lines[i]).join('\n').slice(0,2600);
}
async function searchCatalog(a){
 if(typeof a.query!=='string'||!a.query.trim())throw Error('Пустой запрос');
 const tokens=[...new Set(a.query.replace(/(\d),(\d)/g,'$1.$2').split(/[\s,;]+/).map(norm).filter(Boolean))].slice(0,12);
 const limit=Math.max(1,Math.min(Number(a.limit)||5,8));const candidates=[];
 const catalogs=CATALOGS.filter(c=>(!a.category||c.document.category===a.category)&&(!a.document_id||c.document.id===a.document_id));
 if(a.document_id&&!catalogs.length)throw Error('Неизвестный document_id');
 if(a.category&&!catalogs.length)throw Error('Неизвестная категория. Категории доступны в list_catalogs.');
 const ids=new Set(catalogs.map(c=>c.document.id));
 for(const p of await catalogSearchIndex()){
  if(!ids.has(p.document_id))continue;
  const hits=tokens.filter(t=>p.body.includes(t));if(!hits.length)continue;
  const score=hits.reduce((n,t)=>n+(t.length>3?2:1),0)+(hits.length===tokens.length?5:0);
  candidates.push({document_id:p.document_id,page:p.page,score,matched_tokens:hits});
 }
 candidates.sort((x,y)=>y.score-x.score||x.document_id.localeCompare(y.document_id)||x.page-y.page);
 const items=[];
 for(const hit of candidates.slice(0,limit)){
  const catalog=catalogs.find(c=>c.document.id===hit.document_id);const rows=await catalogPages(catalog);const row=rows.find(p=>p.page===hit.page);
  const excerpt=catalogExcerpt(row.text,tokens);
  items.push({...row,...hit,text:excerpt,truncated:excerpt!==row.text,source_url:catalog.document.source_url,source_modified:catalog.document.modified,requires_visual_review:!!row.ocr||row.text_status==='visual_only'});
 }
 return {query:a.query,snapshot_at:SNAPSHOT_AT,searched_documents:catalogs.length,total_matching_pages:candidates.length,items,notice:'Возвращены краткие фрагменты. Полный текст и соседние страницы читать через read_catalog_page. Не делать технические выводы по обрезанной или нечёткой OCR-таблице.'};
}

const cache=new Map();
async function getProduct(value,refresh=false){
 const original=safeUrl(value);const hit=cache.get(original);
 if(!refresh&&hit&&Date.now()-hit.time<120000)return {...hit.data,cache_used:true};
 let url=original,response;
 const signal=AbortSignal.timeout(12000);
 for(let hop=0;hop<4;hop++){
  response=await fetch(url,{redirect:'manual',signal});
  if(response.status>=300&&response.status<400){url=safeUrl(new URL(response.headers.get('location'),url).toString());continue;}
  break;
 }
 if(!response.ok)throw Error('Карточка недоступна: HTTP '+response.status);
 const html=await response.text();if(html.length>4000000)throw Error('Слишком большой ответ');
 const data={...parseProduct(html,url),checked_at:new Date().toISOString()};
 if(!data.article)throw Error('Артикул товара не найден; страница может быть разделом');
 if(cache.size>=128)cache.delete(cache.keys().next().value);
 cache.set(original,{time:Date.now(),data});return {...data,cache_used:false};
}
const descriptions={
 get_catalog_source:'Получить ссылку на оригинальный PDF или изображение с публичного диска по document_id. Использовать для графиков насосов, размерных чертежей и проверки неоднозначной OCR-таблицы. Не просить клиента повторно присылать уже включённый каталог. Ссылка временная: получать непосредственно перед чтением. Видео можно открыть, но оно не было изучено при импорте.',
 list_catalogs:'Список всех документов с публичного диска Элком, их категории, статус обработки, количество страниц и дата снимка. Использовать для выбора document_id и контроля покрытия. Статус видео listed_video означает, что его содержимое не анализировалось.',
 read_catalog_page:'Прочитать конкретную страницу каталога по document_id и номеру страницы PDF. Возвращает источник, исходный текст, признак OCR и необходимость визуальной проверки. После поиска изучать соседние страницы и расшифровки маркировок. Графики насосов, размерные чертежи и неясные числа проверять по оригинальному PDF.',
 find_supplier_cards:'Быстрый локальный поиск по всему ассортименту сайта: двигатели, редукторы, насосы и комплектующие, автоматика, преобразователи, подшипники, тали, вентиляция и теплотехника. Примеры запросов: 5АИ 100 S4; NMRW110-25/100B5; К 290/30; ЦН 1000-180; артикул. Не передавать лишние слова клиентского запроса. NMRV искать также как NMRW. Найти карточки на основном сайте Элком по обозначению или артикулу. Возвращает только ссылки совпавшие с запросом, без проверки наличия. Отсутствие ссылок не означает отсутствие оборудования. Далее вызвать get_component_stock для подтверждения артикула и наличия.',
 equipment_rules:'Правила подбора оборудования Элком и покрытие базы. В начале работы прочитать правила. Рекомендуемая модель GPT-6.1 Sol; выбор модели осуществляется пользователем в ChatGPT. Подбор насосов и редукторов вне индекса требует подтверждения источниками; не выдумывать артикулы и наличие.',
 search_catalog:'Поиск по заранее извлечённым страницам каталогов. Разбить запрос на обозначения и технические параметры. Возвращает исходный текст, страницу и признак OCR. OCR сканов требует проверки чисел. Синхронные обороты двигателей не путать с рабочими. Использовать для расшифровки маркировок, совместимости и подбора состава.',
 select_motor:'Найти 5АИ по мощности и скорости в электрических таблицах, сразу получить ссылки на карточки. Если заданы лапы, mount=1081; для B5 mount=3081, для B35 mount=2081. check_stock=true проверит отобранные карточки параллельно в том же вызове. АИР сопоставлять с 5АИ, если параметры совпадают. Сначала точная скорость, затем ±15%; индекс содержит синхронные обороты, рабочие уточнять по карточке. Не запрашивать неуказанные доппараметры. Для малых общепромышленных двигателей стандарт 220/380В, подтвердить по карточке.',
 get_component_stock:'Получить артикул и наличие комплектующих с основного сайта Элком без браузера. До 8 карточек, параллельные запросы. Другие региональные поддомены запрещены. Выдать Питер, Москва, Краснодар, Ставрополь и сумму остальных складов. null означает неизвестно, не 0. Указать дату склада и время проверки.',
 get_motor_with_mount_fallback:'Проверить двигатель требуемого исполнения. Если подтверждено отсутствие на всех четырёх приоритетных складах, проверить вариант 3081→2081, B5→B35 или B14→B34. Передать две проверенные карточки. Если наличие неизвестно, автоматическую замену не делать. Совместимость проверить по каталогу.',
 select_gear_motor:'Подбор мотор-редуктора по габариту, выходным оборотам, мощности и монтажу. Сначала точные обороты, затем ±15%. Вернуть состав, источник и наличие каждого компонента. Если в проверенном индексе нет сочетания, использовать search_catalog, затем карточки с get_component_stock. Не выдавать отсутствие записи за отсутствие оборудования у поставщика.'};
const schema=(properties,required=[])=>({type:'object',properties,required,additionalProperties:false});
const outputs={
 find_supplier_cards:{type:'object',required:['query','cards','stock_checked'],properties:{query:{type:'string'},cards:{type:'array',items:{type:'object',required:['url','title','article_verified'],properties:{url:{type:'string'},title:{type:'string'},article:{type:['string','null']},article_verified:{type:'boolean'},requires_card_verification:{type:'boolean'}},additionalProperties:true}},stock_checked:{type:'boolean'},total_matches:{type:'integer'}},additionalProperties:true},
 get_component_stock:{type:'object',required:['items'],properties:{items:{type:'array',items:{type:'object',required:['url'],properties:{url:{type:'string'},article:{type:['string','null']},stock:{type:['object','null'],properties:Object.fromEntries([...rules.warehouses,'Остальные склады'].map(k=>[k,{type:['integer','null']}]))},stock_date:{type:['string','null']},checked_at:{type:'string'},error:{type:'string'}},additionalProperties:true}}},additionalProperties:true},
 prepare_selection:{type:'object',required:['status'],properties:{status:{type:'string',enum:['verified_combination','motor_candidates','requires_engineering_verification']}},additionalProperties:true},
 search_catalog:{type:'object',required:['query','items'],properties:{query:{type:'string'},items:{type:'array',items:{type:'object',required:['document_id','page','text'],properties:{document_id:{type:'string'},page:{type:'integer'},text:{type:'string'},truncated:{type:'boolean'},requires_visual_review:{type:'boolean'}},additionalProperties:true}}},additionalProperties:true},
 select_motor:{type:'object',required:['candidates','supplier_cards','stock_checked'],properties:{candidates:{type:'array',items:{type:'object'}},supplier_cards:{type:'array',items:{type:'object'}},verified_components:{type:'array',items:{type:'object'}},stock_checked:{type:'boolean'}},additionalProperties:true}
};
const tools=[{name:'prepare_selection',description:'Начать подбор оборудования по исходному клиентскому запросу внутри ChatGPT за один вызов. Примеры: АИР двигатель 3/1420 лапы; NMRV 110-56-3-B3; насос К 290/30; ЦН 1000-180. Для известного мотор-редуктора вернёт состав и актуальное наличие, для двигателя — кандидатов и карточки, для насосного агрегата — источники и состав только насосная часть + двигатель, каждый с отдельным артикулом и наличием. Продолжить подбор до подтверждения обеих позиций; карточка агрегата не является составом. Для других моделей — карточки и страницы каталога. Не объявлять найденных кандидатов готовым агрегатом: status=requires_engineering_verification требует проверки состава, совместимости и каждого артикула. Не задавать отсутствующие доппараметры.',inputSchema:schema({request:{type:'string',minLength:3,maxLength:500},refresh:{type:'boolean'}},['request'])},{name:'get_catalog_source',description:descriptions.get_catalog_source,inputSchema:schema({document_id:{type:'string'}},['document_id'])},{name:'list_catalogs',description:descriptions.list_catalogs,inputSchema:schema({category:{type:'string'}})},{name:'read_catalog_page',description:descriptions.read_catalog_page,inputSchema:schema({document_id:{type:'string'},page:{type:'integer',minimum:1}},['document_id','page'])},{name:'find_supplier_cards',description:descriptions.find_supplier_cards,inputSchema:schema({query:{type:'string',minLength:2,maxLength:160},limit:{type:'integer',minimum:1,maximum:12}},['query'])},{name:'equipment_rules',description:descriptions.equipment_rules,inputSchema:schema({})},{name:'search_catalog',description:descriptions.search_catalog,inputSchema:schema({query:{type:'string',minLength:1,maxLength:200},limit:{type:'integer',minimum:1,maximum:8},category:{type:'string'},document_id:{type:'string'}},['query'])},{name:'select_motor',description:descriptions.select_motor,inputSchema:schema({power_kw:{type:'number',exclusiveMinimum:0},rpm:{type:'number',exclusiveMinimum:0},mount:{type:'string',enum:['1081','2081','3081','1082','2082','3082']},check_stock:{type:'boolean'},refresh:{type:'boolean'}},['power_kw','rpm'])},{name:'get_component_stock',description:descriptions.get_component_stock,inputSchema:schema({urls:{type:'array',items:{type:'string'},minItems:1,maxItems:8},refresh:{type:'boolean'}},['urls'])},{name:'get_motor_with_mount_fallback',description:descriptions.get_motor_with_mount_fallback,inputSchema:schema({primary_url:{type:'string'},fallback_url:{type:'string'},primary_mount:{type:'string',enum:['3081','B5','B14']},compatible:{type:'boolean'}},['primary_url','fallback_url','primary_mount','compatible'])},{name:'select_gear_motor',description:descriptions.select_gear_motor,inputSchema:schema({frame:{type:'integer',minimum:1},output_rpm:{type:'number',exclusiveMinimum:0},power_kw:{type:'number',exclusiveMinimum:0},mount:{type:'string'},refresh:{type:'boolean'}},['frame','output_rpm','power_kw','mount'])}].map(t=>({...t,title:({prepare_selection:'Подбор по запросу клиента',find_supplier_cards:'Поиск оборудования Элком',select_motor:'Подбор двигателя',select_gear_motor:'Состав мотор-редуктора',get_component_stock:'Артикулы и остатки комплектующих'})[t.name]||t.name,outputSchema:outputs[t.name]||{type:'object',additionalProperties:true},annotations:{readOnlyHint:true,destructiveHint:false,openWorldHint:['prepare_selection','select_motor','get_catalog_source','get_component_stock','get_motor_with_mount_fallback','select_gear_motor'].includes(t.name)}}));
const norm=s=>s.toUpperCase().replace(/[\s‐–—-]/g,'').replace(/(\d),(\d)/g,'$1.$2').replaceAll('А','A').replaceAll('И','I').replaceAll('Р','R');
function checkDriveCompatibility(reducer,motor){
 const flange=x=>({B35:'B5',B34:'B14','3081':'B5','2081':'B5'})[String(x).toUpperCase()]||String(x||'').toUpperCase();
 const a=flange(reducer.flange),b=flange(motor.flange);const reasons=[];
 if(a&&b&&a!==b)reasons.push('Тип фланца не совпадает: '+a+' / '+b);


 const keys=['shaft_diameter','shaft_length','pilot_diameter','bolt_circle','hole_diameter','bolt_count'];
 for(const k of keys)if(Number.isFinite(reducer[k])&&Number.isFinite(motor[k])&&reducer[k]!==motor[k])reasons.push('Не совпадает '+k);
 if(reasons.length)return {status:'incompatible',selection_complete:false,reasons};
 const missing=keys.filter(k=>!Number.isFinite(reducer[k])||!Number.isFinite(motor[k]));
 if(!a||!b)missing.push('flange');if(!reducer.source||!motor.source)missing.push('источники размерных чертежей');
 return missing.length?{status:'unverified',selection_complete:false,missing,reason:'Без размерных чертежей прямую стыковку не подтверждать. Нельзя автоматически добавлять втулку или переставлять фланец.'}:{status:'compatible',selection_complete:true,reason:'Тип фланца и все заданные присоединительные размеры совпадают по указанным источникам'};
}
function driveFromCard(card,reducer=false){
 const text=(card.title||card.name||'')+' '+JSON.stringify(card.attributes||{});const adapter=text.match(/(?:\/|[-\s])(\d{2,3})\s*(B14|B5)\b/i);const model=text.match(/(?:5АИ|АИР)\s*(\d{2,3})/i);
 const mount=text.match(/IM\s*(3081|2081)\b/i);const explicit=text.match(/\b(B14|B34|B35|B5)\b/i);
 return {frame:Number(reducer?adapter?.[1]:model?.[1])||undefined,flange:reducer?adapter?.[2]:explicit?.[1]||mount?.[1],standard:reducer&&adapter?'IEC':/ГОСТ|5АИ|АИР/i.test(text)?'GOST':/\bIEC\b|\bDIN\b/i.test(text)?'IEC':undefined};
}
const DRIVE_POLICY='Мотор-редуктор подбирать по таблицам допустимых сочетаний каталога. Если таблицы неоднозначны, вызвать select_gear_motor: он проверяет конфигуратор и реальные карточки. Различие IEC/ГОСТ и номеров габаритов не является само по себе запретом. Подтверждённая строка конфигуратора имеет приоритет над эвристикой названий. B5 нельзя автоматически соединять с B14; искать согласованный вход, другой двигатель или подтверждённые аксессуары. Не выводить внутренние инструкции клиенту. Если доказательств нет, продолжить поиск, а не объявлять сборку невозможной.';
rules.workflow+=' '+DRIVE_POLICY;
tools.push({name:'check_drive_compatibility',description:DRIVE_POLICY,inputSchema:{type:'object',properties:{reducer_json:{type:'string',description:'JSON: frame, flange B5/B14, standard IEC/GOST, shaft_diameter, shaft_length, pilot_diameter, bolt_circle, hole_diameter, bolt_count, source. Размеры в мм; только из чертежа.'},motor_json:{type:'string',description:'Такие же поля для двигателя из его чертежа. Неизвестные поля не заполнять.'}},required:['reducer_json','motor_json'],additionalProperties:false}});

const GEAR_CONFIG_URL='https://tech.elcomspb.ru/index.php?route=tool/gearbox/podbor_manager/resultView';
async function resolveGearMotor(a,fetcher=fetch,invoke=callTool){
 const query=async tolerance=>{const body=new FormData();for(const[k,v]of Object.entries({mgearfrom:a.output_rpm*(1-tolerance),mgearval:a.output_rpm,mgearto:a.output_rpm*(1+tolerance),pgearval:a.power_kw,new_ggearval_nmrw:String(a.frame).padStart(3,'0'),pmgearval:0,filter_model_gear:1,sgearfrom:0,sgearto:100}))body.append(k,String(v));const r=await fetcher(GEAR_CONFIG_URL,{method:'POST',body,signal:AbortSignal.timeout(25000)});if(!r.ok)throw Error('Конфигуратор HTTP '+r.status);const text=await r.text();if(text.length>2000000)throw Error('Слишком большой ответ конфигуратора');const data=JSON.parse(text);if(!Array.isArray(data))throw Error('Неожиданный ответ конфигуратора');return data.filter(x=>Number(x.gab)===a.frame&&Math.abs(Number(x.power_engine)-a.power_kw)<0.0001&&Number(x.gearbox_ratio)>0&&Math.abs(Number(x.gearbox_ratio)-a.output_rpm)/a.output_rpm<=tolerance+0.000001)};
 let rows,match_kind='exact';try{rows=await query(0);if(!rows.length){rows=await query(0.15);match_kind='within_15_percent'}}catch(e){return {status:'requires_engineering_verification',selection_complete:false,configurator_error:e.message,notice:'Конфигуратор недоступен. Продолжить по таблицам каталога; отсутствие подтверждения не означает несовместимость.'}}
 const combinations=[];const cache=new Map();const live=async(article)=>{if(cache.has(article))return cache.get(article);const found=await findCards(article,2);const card=found.cards.find(c=>c.article===article||c.url.includes(article));if(!card){cache.set(article,null);return null}const r=await invoke('get_component_stock',{urls:[card.url],refresh:true});const item=(Array.isArray(r)?r:r.items||[])[0];const value=item&&!item.error&&item.article===article?item:null;cache.set(article,value);return value};
 for(const row of rows.slice(0,6)){
 const reducerArticle=String(row.buhta_gear||'').trim(),motorArticles=String(row.buhta_engine||'').trim().split('/').map(x=>x.trim()).filter(Boolean);
 const reducer=await live(reducerArticle);if(!reducer)continue;
 const attrs=reducer.attributes||{},pam=String(attrs['Типоразмер фланца']||attrs['Присоединительный размер к электродвигателю (РАМ)']||'').toUpperCase();
 if(pam!==String(row.pam_name).toUpperCase()||Number(attrs['Передаточное число'])!==Number(row.peredat))continue;
 for(const article of motorArticles){const motor=await live(article);if(!motor)continue;const at=motor.attributes||{};if(Math.abs(Number(String(at['Мощность (кВт)']).replace(',','.'))-a.power_kw)>0.0001)continue;
 const normalize=x=>String(x).toUpperCase().replace(/5AI/g,'5АИ').replace(/B/g,'В').replace(/[^A-ZА-Я0-9]/g,'');
 const wanted=normalize(String(row.to_engine_name).split(/3081|2081|IM|0[.,]75|-/)[0]);if(!normalize(motor.title).includes(wanted))continue;
 const actualFlange=String(at['Монтажное исполнение']||'').toUpperCase(),small=/B14$/i.test(row.pam_name);if(small?!['B14','B34'].includes(actualFlange):!['B5','B35','3081','2081'].includes(actualFlange))continue;
 const accessories=[];const works=String(row.pam_service||'');const serviceArticles=String(row.buhta_service||'').trim().split('/').filter(Boolean);for(const code of serviceArticles)accessories.push(await live(code.trim())||{article:code.trim(),title:works,stock:null,status:'card_not_found'});
 const completeAccessories=accessories.every(x=>!x.status)&&(!works||works==='empty'||accessories.length>0);combinations.push({configurator_row_id:row.id,source:'https://tech.elcomspb.ru/configurator_gearbox/',source_checked_at:new Date().toISOString(),output_rpm:Number(row.gearbox_ratio),input_working_rpm:Number(row.real_ratio_engine),ratio:Number(row.peredat),service_factor:Number(row.sf),torque_nm:Number(row.hm),mount:a.mount,reducer,motor,accessories,assembly_works:works==='empty'?'не указаны':works,compatibility:{status:'compatible',basis:'authoritative_configurator_combination',reducer_article:reducer.article,motor_article:motor.article},selection_complete:completeAccessories,notes:actualFlange==='2081'&&/3081/.test(row.to_engine_name)?['В конфигураторе IM3081; актуальная карточка этого артикула IM2081 (B35 — лапы и большой фланец). Сохранено актуальное исполнение, замена не скрывается.']:[]});break;}
 }
 combinations.sort((a,b)=>Number(b.selection_complete)-Number(a.selection_complete));return {status:combinations.some(c=>c.selection_complete)?'verified_combination':'requires_engineering_verification',selection_complete:combinations.some(c=>c.selection_complete),match_kind,requested:a,combinations,configurator_rows:rows.map(r=>({id:r.id,motor:r.to_engine_name,pam:r.pam_name,reducer_article:String(r.buhta_gear).trim(),motor_articles:String(r.buhta_engine).trim(),accessories:r.pam_service,accessory_article:r.buhta_service})),notice:'Подбор подтверждён строкой конфигуратора и актуальными карточками; доступность в конфигураторе не заменяет складские остатки. Несовпавшие артикулы не подменять автоматически. B3/B8 — положение агрегата.'};
}

async function callTool(name,a){
 if(name==='check_drive_compatibility')return checkDriveCompatibility(JSON.parse(a.reducer_json),JSON.parse(a.motor_json));
 if(name==='prepare_selection'){
  const request=a.request;const pumpRequest=isPumpRequest(request);const gear=request.match(/NMR[VW]\s*[- ]?\s*(\d+)\s*[-– ]\s*(\d+(?:[.,]\d+)?)\s*[-– ]\s*(\d+(?:[.,]\d+)?)\s*[-– ]\s*(B\d+)/i);
  if(gear){
   const parsed={frame:Number(gear[1]),output_rpm:Number(gear[2].replace(',','.')),power_kw:Number(gear[3].replace(',','.')),mount:gear[4].toUpperCase(),refresh:a.refresh};
   const additional_requirements={brake:/тормоз|brake/i.test(request),manual_release:/ручк|ручн.*расторм|manual/i.test(request)};
   if(!additional_requirements.brake&&!additional_requirements.manual_release){const result=await callTool('select_gear_motor',parsed);if(result.combinations?.length||result.configurator_error)return {status:result.selection_complete?'verified_combination':'requires_engineering_verification',...result};}
   const catalog=await searchCatalog({query:'NMRW'+String(parsed.frame).padStart(3,'0'),category:'Редукторы',limit:3});
   const cards=await findCards('NMRW'+String(parsed.frame).padStart(3,'0'),6);
   return {status:'requires_engineering_verification',requested:parsed,additional_requirements,cards:cards.cards,catalog,required_steps:['По таблицам подтвердить точные выходные обороты; затем варианты в пределах ±15%.','Проверить допустимую мощность, коэффициент сервиса, моторный фланец и нужные аксессуары.','Для тормоза и ручного растормаживания проверить отдельное исполнение двигателя.','Подтвердить артикулы и наличие всех комплектующих.'],notice:'Это кандидаты редукторов, а не готовый состав агрегата.'};
  }
  const power=request.match(/(\d+(?:[.,]\d+)?)\s*[/]\s*(\d{3,4})/);
  if(!pumpRequest&&power&&/двигател|АИР|5АИ|motor/i.test(request)&&!/ESQ|АИМУ|5АМУ|МТК|МТН|ВАО|DIN|IEC|итальян|мал(?:ый|ом)\s+флан/i.test(request)){
   let mount;if(/лапы|лапах|\bB3\b|IM\s*1081/i.test(request))mount='1081';else if(/B35|IM\s*2081/i.test(request))mount='2081';else if(/B5|IM\s*3081/i.test(request))mount='3081';
   if(!/тормоз|brake/i.test(request))return {status:'motor_candidates',...await callTool('select_motor',{power_kw:Number(power[1].replace(',','.')),rpm:Number(power[2]),...(mount?{mount}:{}),check_stock:true,refresh:a.refresh})};
  }
  const query=request.replace(/^(?:подбери|подберите|нужен|нужна)\s+/i,'').replace(/^(?:насос(?:ный)?(?:\s+агрегат)?|двигатель|редуктор)\s+/i,'').replace(pumpRequest?/\s+(?:с\s+(?:электро)?двигател(?:ем|ём)|без\s+(?:электро)?двигател(?:я)|б\s*[/]\s*дв).*$/i:/$^/,'').trim();
  const cards=await findCards(query.slice(0,160),6);
  const category=pumpRequest?'Насосы':undefined;
  const catalog=await searchCatalog({query:query.slice(0,200),...(category?{category}:{}),limit:3});
  return {status:'requires_engineering_verification',request,cards:cards.cards,catalog,...(pumpRequest?{equipment_type:'pump_unit',assembly_requirements:pumpAssemblyRequirements(request)}:{}),stock_checked:false,notice:pumpRequest?'Состав насосного агрегата: только насосная часть и электродвигатель. Подтвердить модель, отдельный артикул и наличие каждой позиции. Данные для других комплектующих не запрашивать. Рабочую точку Q/H проверить по исходному графику, если задана.':'Подбор по источникам. Для мотор-редуктора проверить редуктор, двигатель и требуемые комплектующие; артикул и наличие каждого подтвердить get_component_stock.'};
 }
 if(name==='find_supplier_cards')return findCards(a.query,a.limit);
 if(name==='get_catalog_source'){
  const document=CATALOGS.find(c=>c.document.id===a.document_id)?.document;
  if(!document)throw Error('Документ не найден. Использовать list_catalogs для выбора document_id.');
  const query=new URLSearchParams({public_key:rules.catalog_url,path:document.path});
  const response=await fetch('https://cloud-api.yandex.net/v1/disk/public/resources/download?'+query,{redirect:'manual',signal:AbortSignal.timeout(20000)});
  if(!response.ok)throw Error('Оригинал недоступен: HTTP '+response.status);
  const source=await response.json();
  if(!source.href||new URL(source.href).protocol!=='https:')throw Error('Некорректная ссылка на источник');
  return {document_id:document.id,name:document.name,catalog_path:document.path,mime_type:document.mime_type,download_url:source.href,source_folder:rules.catalog_url,source_md5:document.md5,notice:'Временная ссылка на оригинал. Для проверки графика открыть нужную физическую страницу PDF; печатная нумерация может отличаться.'};
 }
 if(name==='list_catalogs')return catalogSummary(a.category);
 if(name==='read_catalog_page')return readCatalogPage(a.document_id,a.page);
 if(name==='equipment_rules')return {...rules,coverage:{site_assortment:ASSORTMENT_META,motor_index_rows:MOTORS.length,snapshot_at:SNAPSHOT_AT,total_documents:CATALOGS.length,indexed_documents:CATALOGS.filter(c=>c.document.status.startsWith('indexed')).length,catalog_pages:CATALOGS.reduce((n,c)=>n+c.document.indexed_pages,0),categories:[...new Set(CATALOGS.map(c=>c.document.category))],verified_gear_motor_combinations:1},limitations:['Модель не принудительно задаётся плагином.','Индекс сайта охватывает все адреса из карты сайта и найденные текущие разделы; технические карточки подтверждаются при подборе.','Проверенная комбинация мотор-редуктора пока одна; другие искать по каталогу и подтверждать.','OCR не является проверенной таблицей чисел. Графики и чертежи требуют чтения оригинального PDF.','Текст всех PDF и изображений включён в поиск; видео не анализировалось.','Наличие проверяется онлайн; отказ сайта возвращает ошибку, а не нули.']};
 if(name==='search_catalog')return searchCatalog(a);
 if(name==='select_motor'){
  const candidates=motorCandidates(MOTORS,a.power_kw,a.rpm);
  const supplier_cards=[];
  for(const candidate of candidates.slice(0,3)){
   const found=await findCards(candidate.name,12);
   for(const card of found.cards){
    const path=new URL(card.url).pathname;
    if(!path.includes('/general-purpose_engines/5ai/')||/ed\d*|et\d*/i.test(path.split('/').at(-2)))continue;
    const mount=card.attributes['Монтажное исполнение:']||card.attributes['Монтажное исполнение'];
    if(a.mount&&mount!==a.mount&&!equipmentNorm(card.title).includes('IM'+a.mount))continue;
    supplier_cards.push({...card,catalog_model:candidate.name});
   }
  }
  let verified_components=[];
  if(a.check_stock&&supplier_cards.length)verified_components=await callTool('get_component_stock',{urls:[...new Set(supplier_cards.map(c=>c.url))].slice(0,4),refresh:a.refresh});
  return {candidates,supplier_cards,verified_components,stock_checked:!!a.check_stock&&verified_components.length>0,requested_mount:a.mount||null,notice:'В каталоге указаны синхронные обороты, а не рабочие. Допуск скорости относится к подбору; не выдавать 1500 за подтверждённые 1420. Для IM1081: лапы; IM3081: B5; IM2081: B35. Стандартное питание малых общепромышленных двигателей 220/380В, подтвердить по карточке.'};
 }
 if(name==='get_component_stock') {if(!Array.isArray(a.urls)||a.urls.length>8)throw Error('До 8 карточек');return Promise.all(a.urls.map(async u=>{try{return await getProduct(u,a.refresh)}catch(e){return {url:u,error:e.message,stock:null}}}));}
 if(name==='get_motor_with_mount_fallback'){
  if(!a.compatible)throw Error('Сначала проверить совместимость по каталогу');
  const primary=await getProduct(a.primary_url);if(!primary.first_four_confirmed_empty)return {selected:primary,used_fallback:false,reason:rules.warehouses.some(c=>primary.stock[c]>0)?'Есть на приоритетном складе':'Наличие не подтверждено полностью; замена не выполнена'};
  const fallback=await getProduct(a.fallback_url);return {primary,selected:fallback,used_fallback:true,mount_transition:a.primary_mount+'→'+rules.mount_fallbacks[a.primary_mount]};
 }
 if(name==='select_gear_motor')return resolveGearMotor(a);
 throw Error('Неизвестный инструмент');
}
function validateArguments(name,args){
 const tool=tools.find(t=>t.name===name);if(!tool)throw Error('Неизвестный инструмент');
 if(!args||typeof args!=='object'||Array.isArray(args))throw Error('Аргументы должны быть объектом');
 for(const k of tool.inputSchema.required)if(args[k]===undefined)throw Error('Не задан параметр '+k);
 for(const [k,v] of Object.entries(args)){
  const d=tool.inputSchema.properties[k];if(!d)throw Error('Неизвестный параметр '+k);
  if(d.type==='array'? !Array.isArray(v):d.type==='integer'? !Number.isInteger(v):typeof v!==d.type)throw Error('Неверный тип '+k);
  if(d.enum&&!d.enum.includes(v))throw Error('Неверное значение '+k);
  if(d.minimum!==undefined&&v<d.minimum||d.maximum!==undefined&&v>d.maximum||d.exclusiveMinimum!==undefined&&v<=d.exclusiveMinimum)throw Error('Параметр вне диапазона '+k);
  if(d.minLength!==undefined&&v.length<d.minLength||d.maxLength!==undefined&&v.length>d.maxLength||d.minItems!==undefined&&v.length<d.minItems||d.maxItems!==undefined&&v.length>d.maxItems)throw Error('Недопустимая длина '+k);
  if(d.items&&v.some(x=>typeof x!==d.items.type))throw Error('Неверные элементы '+k);
 }
}
function toolSummary(name,result){
 if(Array.isArray(result))return 'Проверено карточек: '+result.length+'. Артикулы, характеристики и остатки находятся в structuredContent.items; неизвестное наличие обозначено null.';
 if(result.items)return 'Найдено страниц: '+(result.total_matching_pages??result.items.length)+'. Источники и фрагменты — в structuredContent.items. Для полной страницы вызвать read_catalog_page.';
 if(result.cards)return 'Найдено кандидатов: '+result.total_matches+'. Карточки — в structuredContent.cards. Подтвердить артикулы и наличие инструментом get_component_stock.';
 if(result.documents)return 'Документов: '+result.total_documents+', страниц: '+result.indexed_pages+'. Список — в structuredContent.documents.';
 return 'Результат '+name+' — в structuredContent. Соблюдать правила подбора и не выдавать неизвестные остатки за нули.';
}
function json(value,status=200){return new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}})}

export { callTool, validateArguments, tools, rules, findCards, searchCatalog, catalogSummary, motorCandidates, MOTORS, checkDriveCompatibility, driveFromCard, resolveGearMotor };
